CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(40) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,status ENUM('active','blocked') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,last_login_at TIMESTAMP NULL,INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tournaments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(140) NOT NULL UNIQUE,description TEXT,entry_fee DECIMAL(18,2) NOT NULL DEFAULT 0,prize_pool DECIMAL(18,2) NOT NULL DEFAULT 0,max_participants INT UNSIGNED NOT NULL,registration_closes_at DATETIME NOT NULL,start_at DATETIME NOT NULL,status ENUM('draft','published','open','full','live','completed','cancelled') DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status,start_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS wallets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,available_balance DECIMAL(18,2) NOT NULL DEFAULT 0,reserved_balance DECIMAL(18,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tournament_participants(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,entry_fee DECIMAL(18,2) NOT NULL,status ENUM('joined','cancelled','completed') DEFAULT 'joined',joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(tournament_id,user_id),FOREIGN KEY(tournament_id) REFERENCES tournaments(id) ON DELETE RESTRICT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS wallet_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transaction_uuid CHAR(36) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,type VARCHAR(40) NOT NULL,direction ENUM('credit','debit') NOT NULL,amount DECIMAL(18,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',reference_type VARCHAR(40),reference_id BIGINT UNSIGNED,description VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,INDEX(user_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
